// E7 of row 11 (nhap-excel, AC-6): no cell lost — on the three test files and the answer key written by hand
// (tests/fixtures/nhap-excel/dap-an.json), with no choices and with lua-chon.json, every cell has exactly one of the
// four marks and the answer's reason; the counts of the summary are the counts of the cells; a blocked cell keeps
// «apply» off. The answer key is not generated by the function under test.
import { readFileSync } from "node:fs";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import {
  markTable,
  NO_CHOICES,
  readTable,
  type Choices,
  type LayerView,
  type Mark,
  type UnitFound,
} from "@/modules/imports";

const DIR = join(import.meta.dirname, "fixtures", "nhap-excel");
const KEY = JSON.parse(readFileSync(join(DIR, "dap-an.json"), "utf8")) as {
  units: Record<string, UnitFound>;
  files: Record<
    string,
    Record<string, { createCount: number; canApply: boolean; cells: string[][] }>
  >;
};
const CHOICES = JSON.parse(readFileSync(join(DIR, "lua-chon.json"), "utf8")) as Choices;
const LAYER: LayerView = { labels: [], fields: [], aliases: [], templates: [] };
const MARKS: Mark[] = ["keep", "fixed", "ask", "block"];

async function run(name: string, choices: Choices) {
  const t = await readTable(new Blob([readFileSync(join(DIR, name))]), name);
  if (!t.ok) throw new Error(t.problem);
  return markTable(
    t,
    {
      layer: LAYER,
      today: "2026-11-17",
      units: new Map(Object.entries(KEY.units)),
      listed: new Set(),
    },
    choices,
  );
}

describe("khong-mat-o", () => {
  const runs: [string, string, Choices][] = [
    ["gon.xlsx", "khong-lua-chon", NO_CHOICES],
    ["sheet.csv", "khong-lua-chon", NO_CHOICES],
    ["ban.xlsx", "khong-lua-chon", NO_CHOICES],
    ["ban.xlsx", "lua-chon", CHOICES],
  ];
  for (const [file, run_, choices] of runs)
    it(`${file} · ${run_}: every cell as the answer key`, async () => {
      const want = KEY.files[file]![run_]!;
      const got = await run(file, choices);
      const cells = got.cells.map((r) => r.map((c) => `${c.mark}:${c.why}`));
      let right = 0;
      let total = 0;
      cells.forEach((r, i) =>
        r.forEach((c, j) => {
          total += 1;
          if (c === want.cells[i]?.[j]) right += 1;
          expect(MARKS).toContain(got.cells[i]![j]!.mark);
        }),
      );
      console.log(`o dung ${right}/${total} — ${file} · ${run_}`);
      expect(cells).toEqual(want.cells);
      expect(right).toBe(total);
      const counted = { keep: 0, fixed: 0, ask: 0, block: 0 };
      for (const r of got.cells) for (const c of r) counted[c.mark] += 1;
      expect(got.counts).toEqual(counted);
      expect([got.createCount, got.canApply]).toEqual([want.createCount, want.canApply]);
    });

  it("break: a column without a target leaves its cells without a mark", async () => {
    const got = await run("ban.xlsx", NO_CHOICES);
    const broken = got.cells.map((r, i) =>
      r.map((c, j) => (got.columns[j]!.why === "unknown" ? undefined : c)),
    );
    const hole = broken.findIndex((r) => r.some((c, j) => c === undefined && j === 7));
    expect(() => {
      if (hole >= 0) throw new Error(`cell without mark: ban.xlsx row ${hole + 1} col View`);
    }).toThrow("cell without mark: ban.xlsx row 1 col View");
  });
});
